set role anon;
select test.denied('select app.get_candidate_eligibility()','anonymous cannot read eligibility');
select test.denied('select app.attest_candidate_eligibility(true,true,''adult-pilot-v1'')','anonymous cannot attest');
reset role;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
select test.denied('select app.get_candidate_eligibility()','employer cannot read private declarations');
select test.denied('select app.attest_candidate_eligibility(true,true,''adult-pilot-v1'')','employer cannot attest for a candidate');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000010';
select test.denied('select app.get_candidate_eligibility()','suspended account denied');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000020';
select test.assert(app.get_candidate_eligibility()->>'status'='not_started','profile approval never fabricates a declaration');
select test.denied('select * from private.candidate_pilot_attestations','no direct history access');
select test.invalid('select app.attest_candidate_eligibility(null,true,''adult-pilot-v1'')','explicit age declaration required');
select test.invalid('select app.attest_candidate_eligibility(true,true,''old-policy'')','policy version fixed');
select test.assert(app.attest_candidate_eligibility(false,true,'adult-pilot-v1')->>'status'='not_eligible','under-18 cannot enroll');
select test.assert(not exists(select 1 from jsonb_array_elements(app.list_open_jobs()) j where (j->>'canApply')::boolean),'under-18 cannot apply');
select test.assert(app.attest_candidate_eligibility(true,false,'adult-pilot-v1')->>'status'='not_eligible','both declarations needed');
select test.assert(app.attest_candidate_eligibility(true,true,'adult-pilot-v1')->>'status'='eligible','adult pilot enrolled');
select test.assert(exists(select 1 from jsonb_array_elements(app.list_open_jobs()) j where (j->>'canApply')::boolean),'approved profile plus declarations unlock application');
select test.assert(not(app.get_account_context()->'candidate' ? 'minimumAgeBand'),'account context excludes private fields');
select test.assert(app.attest_candidate_eligibility(true,false,'adult-pilot-v1')->>'status'='not_eligible','candidate can remove eligibility');
select test.assert(not exists(select 1 from jsonb_array_elements(app.list_open_jobs()) j where (j->>'canApply')::boolean),'removal blocks new applications');
reset role;
select test.assert(not exists(select 1 from private.candidate_eligibility where candidate_id='00000000-0000-0000-0000-000000000020'),'removal clears derived gate');
select test.denied('update private.candidate_pilot_attestations set adult=true','declaration history immutable');
select test.denied('delete from private.candidate_pilot_attestations','declaration history cannot be deleted casually');
insert into private.candidate_pilot_attestations(candidate_id,adult,authorized_to_work,policy_version,attested_at,refresh_due_at)
 values('00000000-0000-0000-0000-000000000020',true,true,'adult-pilot-v1',now()-interval '91 days',now()-interval '1 day');
insert into private.candidate_eligibility values('00000000-0000-0000-0000-000000000020',18,true,'adult-pilot-v1',now()-interval '1 day');
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000020';
select test.assert(app.get_candidate_eligibility()->>'status'='expired','expired declaration needs renewal');
select test.assert(not exists(select 1 from jsonb_array_elements(app.list_open_jobs()) j where (j->>'canApply')::boolean),'expired declaration blocks new applications');
select test.assert(app.attest_candidate_eligibility(true,true,'adult-pilot-v1')->>'status'='eligible','renewal records a fresh declaration');
reset role;
select test.assert((select minimum_age_band=18 and policy_version='adult-pilot-v1' and refresh_due_at>now() and refresh_due_at<=now()+interval '90 days' from private.candidate_eligibility where candidate_id='00000000-0000-0000-0000-000000000020'),'server determines band, policy and renewal window');
select 'adult pilot privacy and eligibility checks passed' as result;
